const fs = require('fs');
const path = require('path');

function perform(input, context) {
    const workingDirectory = process.env.BYTECHEF_WORKING_DIR;
    const outputDirectory = process.env.BYTECHEF_OUTPUT_DIR;

    const config = JSON.parse(fs.readFileSync(path.join(workingDirectory, 'config.json'), 'utf8'));
    const [, ...rows] = fs.readFileSync(path.join(workingDirectory, 'orders.csv'), 'utf8').trim().split('\n');

    const totals = {};

    for (const row of rows) {
        const [, customer, amount] = row.split(',');

        totals[customer] = totals[customer] || {orders: 0, total: 0};
        totals[customer].orders += 1;
        totals[customer].total += Number(amount);
    }

    const kept = Object.entries(totals)
        .filter(([, summary]) => summary.total >= config.minimumTotal)
        .sort(([, left], [, right]) => right.total - left.total);

    const reportLines = ['customer,orders,total', ...kept.map(([customer, summary]) =>
        `${customer},${summary.orders},${summary.total.toFixed(2)}`)];
    const chartLines = kept.map(([customer, summary]) =>
        `${customer.padEnd(8)} ${'#'.repeat(Math.round(summary.total / 50))} ${summary.total.toFixed(2)} ${config.currency}`);

    fs.mkdirSync(path.join(outputDirectory, 'charts'), {recursive: true});
    fs.writeFileSync(path.join(outputDirectory, 'report.csv'), reportLines.join('\n') + '\n');
    fs.writeFileSync(path.join(outputDirectory, 'charts', 'summary.txt'), `${process.env.REPORT_TITLE}\n\n${chartLines.join('\n')}\n`);
    fs.writeFileSync(path.join(outputDirectory, 'scratch.log'), 'No Output Files pattern matches this file, so it is not kept.\n');

    console.log(`Wrote a report of ${kept.length} customers`);

    return {
        title: process.env.REPORT_TITLE,
        currency: config.currency,
        customers: kept.length,
        workingDirectoryFiles: fs.readdirSync(workingDirectory).sort(),
    };
}

const fs = require('fs');
const path = require('path');

function perform(input, context) {
    const workingDirectory = process.env.BYTECHEF_WORKING_DIR;

    const [header, ...rows] = fs.readFileSync(path.join(workingDirectory, 'report.csv'), 'utf8').trim().split('\n');
    const summary = fs.readFileSync(path.join(workingDirectory, 'inputs', 'summary.txt'), 'utf8');
    const notes = fs.readFileSync(path.join(workingDirectory, 'notes.txt'), 'utf8');

    const [largestCustomer, , largestTotal] = rows[0].split(',');

    return {
        header,
        rowCount: rows.length,
        largestCustomer,
        largestTotal: Number(largestTotal),
        summaryFirstLine: summary.split('\n')[0],
        notes,
    };
}
